type TriangleMeshCellCounts = {
  c0: number;
  c1: number;
  c2: number;
  chi: number;
  validFaces: number;
  skippedFaces: number;
};

type FundamentalDiagramPreview = {
  width: number;
  height: number;
  boundaryWord: string;
  vertices: Array<{ id: string; x: number; y: number; label: string }>;
  edges: Array<{
    id: string;
    x1: number;
    y1: number;
    x2: number;
    y2: number;
    lx: number;
    ly: number;
    color: string;
    label: string;
    dashed: boolean;
    opacity: number;
    strokeWidth: number;
  }>;
  animatedEdges: Array<{
    id: string;
    x1: number;
    y1: number;
    x2: number;
    y2: number;
    lx: number;
    ly: number;
    color: string;
    label: string;
    dashed: boolean;
    opacity: number;
    strokeWidth: number;
  }>;
};

const boundaryLabelToken = (rawLabel: string | undefined): string => {
  const token = (rawLabel ?? "")
    .trim()
    .toLowerCase()
    .replace(/\^-1$/g, "")
    .replace(/[^a-z0-9]/g, "");
  return token;
};

const boundaryLabelColor = (token: string): string => {
  if (token === "a") return "#dc2626";
  if (token === "b") return "#2563eb";
  if (token === "c") return "#0f766e";
  if (token === "u") return "#7c3aed";
  if (token === "v") return "#ea580c";
  return "#334155";
};

const computeTriangleMeshCellCounts = (mesh: {
  positions: ArrayLike<number>;
  indices?: ArrayLike<number> | null;
}): TriangleMeshCellCounts => {
  const vertexCount = Math.floor((mesh.positions?.length ?? 0) / 3);
  if (vertexCount <= 0) {
    return { c0: 0, c1: 0, c2: 0, chi: 0, validFaces: 0, skippedFaces: 0 };
  }
  const indices = mesh.indices ?? null;
  const triCount = indices && indices.length >= 3 ? Math.floor(indices.length / 3) : Math.floor(vertexCount / 3);
  const edgeSet = new Set<string>();
  let validFaces = 0;
  let skippedFaces = 0;
  const addEdge = (a: number, b: number) => {
    const i0 = Math.min(a, b);
    const i1 = Math.max(a, b);
    edgeSet.add(`${i0}|${i1}`);
  };
  for (let t = 0; t < triCount; t += 1) {
    const base = t * 3;
    const ia = indices ? Number(indices[base]) : base;
    const ib = indices ? Number(indices[base + 1]) : base + 1;
    const ic = indices ? Number(indices[base + 2]) : base + 2;
    const allFinite = Number.isInteger(ia) && Number.isInteger(ib) && Number.isInteger(ic);
    const inRange =
      ia >= 0 && ib >= 0 && ic >= 0 && ia < vertexCount && ib < vertexCount && ic < vertexCount;
    const distinct = ia !== ib && ib !== ic && ia !== ic;
    if (!allFinite || !inRange || !distinct) {
      skippedFaces += 1;
      continue;
    }
    validFaces += 1;
    addEdge(ia, ib);
    addEdge(ib, ic);
    addEdge(ic, ia);
  }
  const c0 = vertexCount;
  const c1 = edgeSet.size;
  const c2 = validFaces;
  return {
    c0,
    c1,
    c2,
    chi: c0 - c1 + c2,
    validFaces,
    skippedFaces,
  };
};

const buildFundamentalDiagramPreview = (
  diagram: FundamentalDiagram,
  opts: { gluePhase?: number } = {}
): FundamentalDiagramPreview => {
  const width = 280;
  const height = 220;
  const pad = 24;
  const vertices = diagram.vertices;
  const gluePhase = clampNumber(opts.gluePhase ?? 0, 0, 1);
  const minX = vertices.reduce((acc, v) => Math.min(acc, v.x), Infinity);
  const maxX = vertices.reduce((acc, v) => Math.max(acc, v.x), -Infinity);
  const minY = vertices.reduce((acc, v) => Math.min(acc, v.y), Infinity);
  const maxY = vertices.reduce((acc, v) => Math.max(acc, v.y), -Infinity);
  const spanX = Math.max(1e-6, maxX - minX);
  const spanY = Math.max(1e-6, maxY - minY);
  const scale = Math.min((width - pad * 2) / spanX, (height - pad * 2) / spanY);
  const toView = (x: number, y: number) => ({
    x: pad + (x - minX) * scale,
    y: height - (pad + (y - minY) * scale),
  });
  const verticesView = vertices.map((vertex) => {
    const p = toView(vertex.x, vertex.y);
    return {
      id: vertex.id,
      x: p.x,
      y: p.y,
      label: diagram.vertexLabels[vertex.id] ?? vertex.id,
    };
  });
  const vertexById = new Map(verticesView.map((vertex) => [vertex.id, vertex]));
  const rawEdges = diagram.edges.flatMap((edge) => {
    const from = vertexById.get(edge.from);
    const to = vertexById.get(edge.to);
    if (!from || !to) return [];
    const orientation = diagram.edgeOrientations[edge.id] ?? 1;
    const start = orientation >= 0 ? from : to;
    const end = orientation >= 0 ? to : from;
    const dx = end.x - start.x;
    const dy = end.y - start.y;
    const len = Math.hypot(dx, dy);
    const nx = len > 1e-6 ? -dy / len : 0;
    const ny = len > 1e-6 ? dx / len : 0;
    const baseLabel = diagram.edgeLabels[edge.id]?.trim() || edge.id;
    const token = boundaryLabelToken(baseLabel);
    const label = orientation >= 0 ? baseLabel : `${baseLabel}^-1`;
    return [
      {
        id: edge.id,
        token,
        dx,
        dy,
        len,
        nx,
        ny,
        x1: start.x,
        y1: start.y,
        x2: end.x,
        y2: end.y,
        lx: (start.x + end.x) * 0.5 + nx * 11,
        ly: (start.y + end.y) * 0.5 + ny * 11,
        color: boundaryLabelColor(token),
        label,
        dashed: orientation < 0,
        opacity: 0.9,
        strokeWidth: 2.4,
      },
    ];
  });
  const labelCenterMap = new Map<string, { x: number; y: number; count: number }>();
  for (const edge of rawEdges) {
    if (!edge.token) continue;
    const prev = labelCenterMap.get(edge.token);
    const midX = (edge.x1 + edge.x2) * 0.5;
    const midY = (edge.y1 + edge.y2) * 0.5;
    if (!prev) {
      labelCenterMap.set(edge.token, { x: midX, y: midY, count: 1 });
      continue;
    }
    prev.x += midX;
    prev.y += midY;
    prev.count += 1;
  }
  for (const [token, center] of labelCenterMap.entries()) {
    if (center.count <= 0) continue;
    labelCenterMap.set(token, { x: center.x / center.count, y: center.y / center.count, count: center.count });
  }
  const animatedEdges =
    gluePhase <= 0
      ? []
      : rawEdges.map((edge) => {
          const center = edge.token ? labelCenterMap.get(edge.token) : null;
          if (!center || center.count <= 1) {
            return {
              id: edge.id,
              x1: edge.x1,
              y1: edge.y1,
              x2: edge.x2,
              y2: edge.y2,
              lx: edge.lx,
              ly: edge.ly,
              color: edge.color,
              label: edge.label,
              dashed: edge.dashed,
              opacity: 0.36,
              strokeWidth: 1.8,
            };
          }
          const midX = (edge.x1 + edge.x2) * 0.5;
          const midY = (edge.y1 + edge.y2) * 0.5;
          const targetMidX = midX + (center.x - midX) * gluePhase;
          const targetMidY = midY + (center.y - midY) * gluePhase;
          const dirX = edge.len > 1e-6 ? edge.dx / edge.len : 1;
          const dirY = edge.len > 1e-6 ? edge.dy / edge.len : 0;
          const edgeScale = 1 - 0.55 * gluePhase;
          const halfLen = Math.max(5, edge.len * edgeScale * 0.5);
          const x1 = targetMidX - dirX * halfLen;
          const y1 = targetMidY - dirY * halfLen;
          const x2 = targetMidX + dirX * halfLen;
          const y2 = targetMidY + dirY * halfLen;
          const nx = -dirY;
          const ny = dirX;
          return {
            id: edge.id,
            x1,
            y1,
            x2,
            y2,
            lx: targetMidX + nx * 9,
            ly: targetMidY + ny * 9,
            color: edge.color,
            label: edge.label,
            dashed: edge.dashed,
            opacity: 0.94,
            strokeWidth: 2.4,
          };
        });
  const faceId = diagram.faces[0]?.id ?? "";
  return {
    width,
    height,
    boundaryWord: diagram.faceBoundaryWords[faceId] ?? "",
    vertices: verticesView,
    edges: rawEdges.map((edge) => ({
      id: edge.id,
      x1: edge.x1,
      y1: edge.y1,
      x2: edge.x2,
      y2: edge.y2,
      lx: edge.lx,
      ly: edge.ly,
      color: edge.color,
      label: edge.label,
      dashed: edge.dashed,
      opacity: edge.opacity,
      strokeWidth: edge.strokeWidth,
    })),
    animatedEdges,
  };
};

const tokenizeScriptLine = (line: string): string[] =>
  (line.match(/"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\S+/g) ?? []).map((token) => {
    if (
      (token.startsWith('"') && token.endsWith('"')) ||
      (token.startsWith("'") && token.endsWith("'"))
    ) {
      return token
        .slice(1, -1)
        .replace(/\\(["'])/g, "$1")
        .replace(/\\\\/g, "\\");
    }
    return token;
  });

const parseScriptBool = (value: string): boolean | null => {
  const raw = value.trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(raw)) return true;
  if (["0", "false", "no", "off"].includes(raw)) return false;
  return null;
};

const parseScriptColor = (value: string): number | null => {
  const raw = value.trim();
  if (/^#?[0-9a-fA-F]{6}$/.test(raw)) {
    const hex = raw.startsWith("#") ? raw.slice(1) : raw;
    return Number.parseInt(hex, 16);
  }
  if (/^0x[0-9a-fA-F]{6}$/.test(raw)) {
    return Number.parseInt(raw.slice(2), 16);
  }
  const numeric = Number(raw);
  if (!Number.isFinite(numeric)) return null;
  return clampNumber(Math.round(numeric), 0, 0xffffff);
};

const cloneGeometryObject = (obj: GeometryObject): GeometryObject => ({
  ...obj,
  params: { ...obj.params },
  transform: {
    position: { ...obj.transform.position },
    rotation: { ...obj.transform.rotation },
    scale: { ...obj.transform.scale },
  },
  material: { ...obj.material },
});

const buildMeshEdgePolylines = (
  mesh: { positions: ArrayLike<number>; indices?: ArrayLike<number> | null },
  includeCoplanar = true,
  angleThresholdDeg = 2
): PolylineSet => {
  const positions = mesh.positions;
  const vertCount = Math.floor(positions.length / 3);
  if (!vertCount) return [];
  const indices = mesh.indices;
  const triCount = indices?.length ? Math.floor(indices.length / 3) : Math.floor(vertCount / 3);
  if (!triCount) return [];

  type EdgeInfo = {
    a: number;
    b: number;
    n0?: { x: number; y: number; z: number };
    n1?: { x: number; y: number; z: number };
  };
  const edgeMap = new Map<string, EdgeInfo>();
  const cosThreshold = Math.cos((Math.max(0, angleThresholdDeg) * Math.PI) / 180);

  const getPos = (idx: number) => {
    const base = idx * 3;
    return {
      x: Number(positions[base] ?? 0),
      y: Number(positions[base + 1] ?? 0),
      z: Number(positions[base + 2] ?? 0),
    };
  };

  const addEdge = (a: number, b: number, normal: { x: number; y: number; z: number } | null) => {
    const i0 = Math.max(0, Math.min(a, b));
    const i1 = Math.max(0, Math.max(a, b));
    const key = `${i0}|${i1}`;
    const prev = edgeMap.get(key);
    if (!prev) {
      edgeMap.set(key, { a: i0, b: i1, n0: normal ?? undefined });
      return;
    }
    if (!prev.n1 && normal) prev.n1 = normal;
  };

  const triNormal = (ia: number, ib: number, ic: number) => {
    const a = getPos(ia);
    const b = getPos(ib);
    const c = getPos(ic);
    const abx = b.x - a.x;
    const aby = b.y - a.y;
    const abz = b.z - a.z;
    const acx = c.x - a.x;
    const acy = c.y - a.y;
    const acz = c.z - a.z;
    const nx = aby * acz - abz * acy;
    const ny = abz * acx - abx * acz;
    const nz = abx * acy - aby * acx;
    const len = Math.hypot(nx, ny, nz);
    if (!Number.isFinite(len) || len <= 1e-12) return null;
    return { x: nx / len, y: ny / len, z: nz / len };
  };

  for (let t = 0; t < triCount; t++) {
    const base = t * 3;
    const ia = indices ? Number(indices[base]) : base;
    const ib = indices ? Number(indices[base + 1]) : base + 1;
    const ic = indices ? Number(indices[base + 2]) : base + 2;
    if (!Number.isFinite(ia) || !Number.isFinite(ib) || !Number.isFinite(ic)) continue;
    if (ia < 0 || ib < 0 || ic < 0 || ia >= vertCount || ib >= vertCount || ic >= vertCount) continue;
    const normal = triNormal(ia, ib, ic);
    addEdge(ia, ib, normal);
    addEdge(ib, ic, normal);
    addEdge(ic, ia, normal);
  }

  const lines: PolylineSet = [];
  for (const edge of edgeMap.values()) {
    if (!includeCoplanar && edge.n0 && edge.n1) {
      const dot = edge.n0.x * edge.n1.x + edge.n0.y * edge.n1.y + edge.n0.z * edge.n1.z;
      if (dot >= cosThreshold) continue;
    }
    const a = getPos(edge.a);
    const b = getPos(edge.b);
    if (
      !Number.isFinite(a.x) ||
      !Number.isFinite(a.y) ||
      !Number.isFinite(a.z) ||
      !Number.isFinite(b.x) ||
      !Number.isFinite(b.y) ||
      !Number.isFinite(b.z)
    ) {
      continue;
    }
    lines.push([a, b]);
  }
  return lines;
};

const buildGeometryTransformMatrix = (transform: GeometryObjectTransform) => {
  const pos = transform.position;
  const rot = transform.rotation;
  const scale = transform.scale;
  const safeScale = new THREE.Vector3(
    toSafeNumber(scale.x, 1) || 1,
    toSafeNumber(scale.y, 1) || 1,
    toSafeNumber(scale.z, 1) || 1
  );
  safeScale.x = Math.max(1e-6, safeScale.x);
  safeScale.y = Math.max(1e-6, safeScale.y);
  safeScale.z = Math.max(1e-6, safeScale.z);
  const euler = new THREE.Euler(
    (toSafeNumber(rot.x, 0) * Math.PI) / 180,
    (toSafeNumber(rot.y, 0) * Math.PI) / 180,
    (toSafeNumber(rot.z, 0) * Math.PI) / 180,
    "XYZ"
  );
  const quat = new THREE.Quaternion().setFromEuler(euler);
  const mat = new THREE.Matrix4();
  mat.compose(
    new THREE.Vector3(toSafeNumber(pos.x, 0), toSafeNumber(pos.y, 0), toSafeNumber(pos.z, 0)),
    quat,
    safeScale
  );
  return mat;
};

const applyGeometryTransformToPolylineSet = (
  lines: PolylineSet,
  transform: GeometryObjectTransform
): PolylineSet => {
  if (!lines.length) return [];
  const mat = buildGeometryTransformMatrix(transform);
  return lines.map((line) =>
    line.map((p) => {
      const v = new THREE.Vector3(p.x, p.y, p.z).applyMatrix4(mat);
      return { x: v.x, y: v.y, z: v.z };
    })
  );
};

const transformSurfaceMeshByGeometryTransform = (
  mesh: SurfaceMeshData,
  transform: GeometryObjectTransform
): SurfaceMeshData => {
  const mat = buildGeometryTransformMatrix(transform);
  const positions = Float32Array.from(mesh.positions);
  const tmp = new THREE.Vector3();
  for (let i = 0; i + 2 < positions.length; i += 3) {
    tmp.set(positions[i], positions[i + 1], positions[i + 2]).applyMatrix4(mat);
    positions[i] = tmp.x;
    positions[i + 1] = tmp.y;
    positions[i + 2] = tmp.z;
  }
  return {
    ...mesh,
    positions,
    indices: mesh.indices ? Uint32Array.from(mesh.indices) : null,
    normals: null,
    uvs: mesh.uvs ? Float32Array.from(mesh.uvs) : null,
    adjacency: null,
    meanEdgeLength: null,
    validation: null,
  };
};

const computeSurfaceMeshFocus = (
  mesh: Pick<SurfaceMeshData, "positions">
): { center: { x: number; y: number; z: number }; radius: number } | null => {
  const positions = mesh.positions;
  if (!positions || positions.length < 3) return null;
  let minX = Infinity;
  let minY = Infinity;
  let minZ = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  let maxZ = -Infinity;
  for (let i = 0; i + 2 < positions.length; i += 3) {
    const x = Number(positions[i]);
    const y = Number(positions[i + 1]);
    const z = Number(positions[i + 2]);
    if (!Number.isFinite(x) || !Number.isFinite(y) || !Number.isFinite(z)) continue;
    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (z < minZ) minZ = z;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
    if (z > maxZ) maxZ = z;
  }
  if (!Number.isFinite(minX) || !Number.isFinite(maxX)) return null;
  const center = {
    x: (minX + maxX) * 0.5,
    y: (minY + maxY) * 0.5,
    z: (minZ + maxZ) * 0.5,
  };
  let radiusSq = 0;
  for (let i = 0; i + 2 < positions.length; i += 3) {
    const dx = Number(positions[i]) - center.x;
    const dy = Number(positions[i + 1]) - center.y;
    const dz = Number(positions[i + 2]) - center.z;
    if (!Number.isFinite(dx) || !Number.isFinite(dy) || !Number.isFinite(dz)) continue;
    const d2 = dx * dx + dy * dy + dz * dz;
    if (d2 > radiusSq) radiusSq = d2;
  }
  return {
    center,
    radius: Math.max(0.2, Math.sqrt(Math.max(0, radiusSq))),
  };
};

type MeshFeatureAnalysis = {
  sharpEdges: PolylineSet;
  faceNormals: PolylineSet;
  dihedralLabels: Array<{ text: string; position: { x: number; y: number; z: number } }>;
  angleDefects: Array<{ point: { x: number; y: number; z: number }; defect: number }>;
};

const analyzeMeshFeatures = (
  mesh: { positions: ArrayLike<number>; indices?: ArrayLike<number> | null },
  dihedralThresholdDeg: number,
  faceNormalScale: number
): MeshFeatureAnalysis => {
  const positions = mesh.positions;
  const indices = mesh.indices ?? null;
  const vertexCount = Math.floor(positions.length / 3);
  const triCount = indices ? Math.floor(indices.length / 3) : Math.floor(vertexCount / 3);
  if (!vertexCount || !triCount) {
    return { sharpEdges: [], faceNormals: [], dihedralLabels: [], angleDefects: [] };
  }

  const getPos = (idx: number) => {
    const base = idx * 3;
    return new THREE.Vector3(
      Number(positions[base] ?? 0),
      Number(positions[base + 1] ?? 0),
      Number(positions[base + 2] ?? 0)
    );
  };
  const safeAcos = (value: number) => Math.acos(clampNumber(value, -1, 1));

  const faceNormals: THREE.Vector3[] = new Array(triCount);
  const faceCenters: THREE.Vector3[] = new Array(triCount);
  const cornerIndices: Array<[number, number, number]> = [];
  const vertexAngleSum = new Float64Array(vertexCount);
  const boundaryVertex = new Uint8Array(vertexCount);

  type EdgeInfo = { a: number; b: number; face0: number; face1: number | null };
  const edges = new Map<string, EdgeInfo>();
  const addEdge = (a: number, b: number, faceIndex: number) => {
    const i0 = Math.min(a, b);
    const i1 = Math.max(a, b);
    const key = `${i0}|${i1}`;
    const existing = edges.get(key);
    if (!existing) {
      edges.set(key, { a: i0, b: i1, face0: faceIndex, face1: null });
      return;
    }
    if (existing.face1 == null) existing.face1 = faceIndex;
  };

  for (let t = 0; t < triCount; t++) {
    const base = t * 3;
    const ia = indices ? Number(indices[base]) : base;
    const ib = indices ? Number(indices[base + 1]) : base + 1;
    const ic = indices ? Number(indices[base + 2]) : base + 2;
    if (
      !Number.isInteger(ia) ||
      !Number.isInteger(ib) ||
      !Number.isInteger(ic) ||
      ia < 0 ||
      ib < 0 ||
      ic < 0 ||
      ia >= vertexCount ||
      ib >= vertexCount ||
      ic >= vertexCount
    ) {
      continue;
    }
    cornerIndices.push([ia, ib, ic]);

    const a = getPos(ia);
    const b = getPos(ib);
    const c = getPos(ic);
    const ab = b.clone().sub(a);
    const ac = c.clone().sub(a);
    const bc = c.clone().sub(b);
    const normal = new THREE.Vector3().crossVectors(ab, ac);
    const nLen = normal.length();
    if (nLen <= 1e-12 || !Number.isFinite(nLen)) {
      faceNormals[t] = new THREE.Vector3(0, 1, 0);
    } else {
      normal.multiplyScalar(1 / nLen);
      faceNormals[t] = normal;
    }
    faceCenters[t] = a.clone().add(b).add(c).multiplyScalar(1 / 3);

    const abDir = ab.clone().normalize();
    const acDir = ac.clone().normalize();
    const baDir = a.clone().sub(b).normalize();
    const bcDir = bc.clone().normalize();
    const caDir = a.clone().sub(c).normalize();
    const cbDir = b.clone().sub(c).normalize();
    if (Number.isFinite(abDir.lengthSq()) && Number.isFinite(acDir.lengthSq())) {
      vertexAngleSum[ia] += safeAcos(abDir.dot(acDir));
    }
    if (Number.isFinite(baDir.lengthSq()) && Number.isFinite(bcDir.lengthSq())) {
      vertexAngleSum[ib] += safeAcos(baDir.dot(bcDir));
    }
    if (Number.isFinite(caDir.lengthSq()) && Number.isFinite(cbDir.lengthSq())) {
      vertexAngleSum[ic] += safeAcos(caDir.dot(cbDir));
    }

    addEdge(ia, ib, t);
    addEdge(ib, ic, t);
    addEdge(ic, ia, t);
  }

  const threshold = Math.max(0, Number(dihedralThresholdDeg) || 0);
  const sharpEdges: PolylineSet = [];
  const faceNormalLines: PolylineSet = [];
  const dihedralLabels: Array<{ text: string; position: { x: number; y: number; z: number } }> = [];

  if (faceNormalScale > 0) {
    for (let t = 0; t < faceCenters.length; t++) {
      const center = faceCenters[t];
      const normal = faceNormals[t];
      if (!center || !normal) continue;
      const end = center.clone().addScaledVector(normal, faceNormalScale);
      faceNormalLines.push(
        [
          { x: center.x, y: center.y, z: center.z },
          { x: end.x, y: end.y, z: end.z },
        ]
      );
    }
  }

  for (const edge of edges.values()) {
    const a = getPos(edge.a);
    const b = getPos(edge.b);
    const isBoundary = edge.face1 == null;
    if (isBoundary) {
      boundaryVertex[edge.a] = 1;
      boundaryVertex[edge.b] = 1;
      sharpEdges.push([
        { x: a.x, y: a.y, z: a.z },
        { x: b.x, y: b.y, z: b.z },
      ]);
      continue;
    }
    const n0 = faceNormals[edge.face0];
    const n1 = faceNormals[edge.face1!];
    if (!n0 || !n1) continue;
    const angleDeg = safeAcos(n0.dot(n1)) * RAD_TO_DEG;
    if (angleDeg >= threshold) {
      sharpEdges.push([
        { x: a.x, y: a.y, z: a.z },
        { x: b.x, y: b.y, z: b.z },
      ]);
    }
    const mid = a.clone().add(b).multiplyScalar(0.5);
    dihedralLabels.push({
      text: `${angleDeg.toFixed(1)}deg`,
      position: { x: mid.x, y: mid.y, z: mid.z },
    });
  }

  const angleDefects: Array<{ point: { x: number; y: number; z: number }; defect: number }> = [];
  for (let i = 0; i < vertexCount; i++) {
    const expected = boundaryVertex[i] ? Math.PI : Math.PI * 2;
    const defect = expected - vertexAngleSum[i];
    if (!Number.isFinite(defect) || Math.abs(defect) < 1e-4) continue;
    const p = getPos(i);
    angleDefects.push({ point: { x: p.x, y: p.y, z: p.z }, defect });
  }

  return { sharpEdges, faceNormals: faceNormalLines, dihedralLabels, angleDefects };
};

