  const [graphProbeToken, setGraphProbeToken] = useState(0);
  const [implicitProbeXYZ, setImplicitProbeXYZ] = useState<{ x: number; y: number; z: number } | null>(null);
  const [implicitProbeToken, setImplicitProbeToken] = useState(0);

