                onChangeCalculusVectorDensity={setCalculusVectorDensity}
                calculusVectorScale={calculusVectorScale}
                onChangeCalculusVectorScale={setCalculusVectorScale}
                calculusHeatmapEnabled={calculusHeatmapEnabled}
