const resolveGalleryAssetPath = (relativePath: string): string => {
  const normalized = relativePath.replace(/^\/+/, "");
  const inGalleryRoot = normalized.startsWith("gallery-images/");
  const base =
    typeof document !== "undefined" && document.baseURI
      ? document.baseURI
      : typeof window !== "undefined" && window.location?.href
        ? window.location.href
        : "/";
  // Desktop runs from file:///.../renderer/dist/index.html.
  // Captured thumbnails live at repo/app root: ../../gallery-images/...
  // Rebase only those paths so rendered cards resolve instead of falling back to diagrams.
  let resolvedPath = normalized;
  if (inGalleryRoot && typeof window !== "undefined" && window.location?.protocol === "file:") {
    resolvedPath = `../../${normalized}`;
  }
  try {
    return new URL(resolvedPath, base).toString();
  } catch {
    return `./${resolvedPath}`;
  }
};

const capturedPresetThumbPath = (id: string, kind: PresetThumbKind): string | null => {
  const normalizedId = kind === "weierstrass" && id.startsWith("w-") ? id.slice(2) : id;
  const capturedIds = CAPTURED_PRESET_IDS_BY_KIND[kind];
  if (!capturedIds?.has(normalizedId)) return null;
  if (kind === "graph") return resolveGalleryAssetPath(`gallery-images/captured/surfaces/explicit/${normalizedId}.png`);
  if (kind === "implicit") return resolveGalleryAssetPath(`gallery-images/captured/surfaces/implicit/${normalizedId}.png`);
  if (kind === "parametric") return resolveGalleryAssetPath(`gallery-images/captured/surfaces/parametric/${normalizedId}.png`);
  if (kind === "spline") return resolveGalleryAssetPath(`gallery-images/captured/surfaces/spline/${normalizedId}.png`);
  if (kind === "mesh") return resolveGalleryAssetPath(`gallery-images/captured/mesh/${normalizedId}.png`);
  if (kind === "rotational") {
    return resolveGalleryAssetPath(`gallery-images/captured/surfaces/constructed/rotational/${normalizedId}.png`);
  }
  if (kind === "sweep") return resolveGalleryAssetPath(`gallery-images/captured/surfaces/constructed/sweep/${normalizedId}.png`);
  if (kind === "tube") return resolveGalleryAssetPath(`gallery-images/captured/surfaces/constructed/tube/${normalizedId}.png`);
  if (kind === "ruled") return resolveGalleryAssetPath(`gallery-images/captured/surfaces/constructed/ruled/${normalizedId}.png`);
  if (kind === "weierstrass") return resolveGalleryAssetPath(`gallery-images/captured/surfaces/weierstrass/${normalizedId}.png`);
  return null;
};

const makePresetThumb = (
  id: string,
  label: string,
  subtitle: string,
  kind: PresetThumbKind,
  viewMode: GalleryCardViewMode = "rendered"
): string => {
  if (viewMode === "rendered") {
    const captured = capturedPresetThumbPath(id, kind);
    if (captured) return captured;
  }
  const key = `${id}|${label}|${subtitle}|${kind}|${viewMode}`;
  const cached = PRESET_THUMB_CACHE.get(key);
  if (cached) return cached;

  const palette =
    kind === "graph"
      ? { top: "#dbeafe", bottom: "#e0f2fe", stroke: "#1d4ed8", ink: "#1e3a8a" }
      : kind === "implicit"
        ? { top: "#dcfce7", bottom: "#d1fae5", stroke: "#0f766e", ink: "#115e59" }
        : kind === "spline"
          ? { top: "#ede9fe", bottom: "#ddd6fe", stroke: "#6d28d9", ink: "#4c1d95" }
          : kind === "sweep"
            ? { top: "#cffafe", bottom: "#e0f2fe", stroke: "#0f766e", ink: "#134e4a" }
            : kind === "tube"
              ? { top: "#dcfce7", bottom: "#ecfccb", stroke: "#166534", ink: "#14532d" }
              : kind === "ruled"
                ? { top: "#fef3c7", bottom: "#fde68a", stroke: "#b45309", ink: "#78350f" }
                : kind === "rotational"
                  ? { top: "#dbeafe", bottom: "#dcfce7", stroke: "#1d4ed8", ink: "#1e3a8a" }
                  : kind === "weierstrass"
                    ? { top: "#f5f3ff", bottom: "#e9d5ff", stroke: "#7c3aed", ink: "#581c87" }
                    : kind === "constructed"
                      ? { top: "#ede9fe", bottom: "#dbeafe", stroke: "#4338ca", ink: "#312e81" }
                      : { top: "#e0f2fe", bottom: "#dbeafe", stroke: "#1d4ed8", ink: "#1e3a8a" };
  const shape = presetSilhouetteSvg(id, kind, palette.stroke);

  const toneTag =
    kind === "graph"
      ? "z=f(x,y)"
      : kind === "implicit"
        ? "f(x,y,z)=0"
        : kind === "spline"
          ? "spline"
          : kind;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="320" height="200" viewBox="0 0 180 90" preserveAspectRatio="none">
<defs>
  <linearGradient id="g" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${palette.top}" />
    <stop offset="100%" stop-color="${palette.bottom}" />
  </linearGradient>
</defs>
<rect x="0.5" y="0.5" width="179" height="89" rx="12" fill="url(#g)" stroke="#d1d5db" />
<rect x="12" y="14" width="156" height="56" rx="10" fill="#ffffff" opacity="0.24" />
<path d="M16 24 H164 M16 38 H164 M16 52 H164 M16 66 H164" stroke="#ffffff" opacity="0.26" />
${shape}
<rect x="10" y="68" width="160" height="12" rx="5" fill="#ffffff" opacity="0.86" />
<text x="14" y="76" font-family="Segoe UI, Arial, sans-serif" font-size="8.1" font-weight="700" fill="${palette.ink}">${escapeSvgText(label)}</text>
<text x="14" y="13" font-family="Segoe UI, Arial, sans-serif" font-size="7.4" fill="${palette.ink}" opacity="0.85">${escapeSvgText(toneTag)}</text>
</svg>`;

  const url = `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
  PRESET_THUMB_CACHE.set(key, url);
  return url;
};

